indowShiftMul, LinearMap.comp_apply, LinearEquiv.coe_coe,\\n    LinearEquiv.coe_ofEq_apply, sectionMulBilin_apply_coe]\\n\\nset_option maxHeartbeats 1600000 in\\n-- Base change preserves the seed-window multiplication square.\\nprivate theorem divUniversalHighWindowBaseChangeShiftMul_zero_zeroEquiv\\n    (a : HS) (x : RZ ⊗[k] HM) :\\n    (LinearMap.baseChange RZ\\n      (divUniversalHighWindowShiftMul (C := C) (pi := pi) hpi g 0 a))\\n        (LinearMap.baseChange RZ\\n          (divUniversalHighWindowZeroEquiv (C := C) (pi := pi) hpi g).toLinearMap x) =\\n      (LinearMap.baseChange RZ\\n        (divUniversalHighWindowOneEquiv (C := C) (pi := pi) hpi g).toLinearMap)\\n        (LinearMap.baseChange RZ (windowShiftMul hpi g a) x) := by\\n  change\\n    ((LinearMap.baseChange RZ\\n      (divUniversalHighWindowShiftMul (C := C) (pi := pi) hpi g 0 a)).comp\\n        (LinearMap.baseChange RZ\\n          (divUniversalHighWindowZeroEquiv (C := C) (pi := pi) hpi g).toLinearMap)) x =\\n      ((LinearMap.baseChange RZ\\n        (divUniversalHighWindowOneEquiv (C := C) (pi := pi) hpi g).toLinearMap).comp\\n          (LinearMap.baseChange RZ (windowShiftMul hpi g a))) x\\n  rw [← LinearMap.baseChange_comp, ← LinearMap.baseChange_comp,\\n    divUniversalHighWindowShiftMul_zero_comp_zeroEquiv]\\n\\nset_option maxHeartbeats 1600000 in\\n-- A single basis product is one coordinate of the universal multiplication map.\\nprivate theorem baseChange_windowShiftMul_finBasis_mem_universalMulSpan\\n    (t : Fin (Module.finrank k HS))\\n    (x : ↥(divUniversalFstWindow C pi hpi g r1 r2 b1 b2 i j).toSubmodule) :\\n    LinearMap.baseChange RZ\\n        (windowShiftMul hpi g ((Module.finBasis k HS) t)) x.1 ∈\\n      universalMulSpan (hπ := hpi) g r1 r2 b1 b2 i j := by\\n  classical\\n  refine ⟨Pi.single t x, ?_⟩\\n  rw [universalMulMap, LinearMap.sum_apply]\\n  simp only [LinearMap.comp_apply, LinearMap.proj_apply]\\n  rw [Finset.sum_eq_single t]\\n  · rw [Pi.single_eq_same]\\n    rfl\\n  · intro s _ hst\\n    rw [Pi.single_eq_of_ne hst, map_zero]\\n    exact (LinearMap.baseChange RZ\\n      (windowShiftMul hpi g ((Module.finBasis k HS) s))).map_zero\\n  · intro ht\\n    exact (ht (Finset.mem_univ t)).elim\\n\\nset_option maxHeartbeats 1600000 in\\n-- The generic stage-zero span is transported from the seed multiplication span.\\nprivate theorem divUniversalHighWindowMulSpan_zero_relation_le_one :\\n    divUniversalHighWindowMulSpan (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 0\\n        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j 0) ≤\\n      divUniversalHighWindowRelation (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 1 := by\\n  classical\\n  rw [divUniversalHighWindowRelation_one_transport]\\n  rintro _ ⟨v, rfl⟩\\n  rw [divUniversalHighWindowMulMap, LinearMap.sum_apply]\\n  apply Submodule.sum_mem\\n  intro t ht\\n  simp only [LinearMap.comp_apply, LinearMap.proj_apply]\\n  have hvt := (v t).2\\n  rw [divUniversalHighWindowRelation_zero,\\n    divUniversalHighWindowStageZero_toSubmodule] at hvt\\n  rcases hvt with ⟨x, hx, hxv⟩\\n  let x' : ↥(divUniversalFstWindow C pi hpi g r1 r2 b1 b2 i j).toSubmodule :=\\n    ⟨x, hx⟩\\n  refine ⟨LinearMap.baseChange RZ\\n      (windowShiftMul hpi g ((Module.finBasis k HS) t)) x,\\n    baseChange_windowShiftMul_finBasis_mem_universalMulSpan\\n      (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j t x', ?_⟩\\n  rw [← hxv]\\n  exact (divUniversalHighWindowBaseChangeShiftMul_zero_zeroEquiv\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j\\n      ((Module.finBasis k HS) t) x).symm\\n\\nset_option maxHeartbeats 1600000 in\\n-- Unfolding both transported seed stages is definitionally expensive.\\n/-- Multiplication by any base-field multiplier preserves the relation tower at\\nits initial transition. -/\\ntheorem map_divUniversalHighWindowBaseMultiplierTransition_relation_zero_le\\n    (a : HS) :\\n    Submodule.map\\n        (divUniversalHighWindowBaseMultiplierTransition (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j 0 a)\\n        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j 0) ≤\\n      divUniversalHighWindowRelation (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 1 :=\\n  (map_divUniversalHighWindowBaseMultiplierTransition_le_mulSpan\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j 0\\n      (divUniversalHighWindowRelation (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 0) a).trans\\n    (divUniversalHighWindowMulSpan_zero_relation_le_one\\n      (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j)\\n\\nset_option maxHeartbeats 1600000 in\\n-- The zero branch unfolds the transported seed multiplication span.\\n/-- Multiplication by any base-field multiplier preserves the recursive\\nhigh-window relation tower at every stage. -/\\ntheorem map_divUniversalHighWindowBaseMultiplierTransition_relation_le\\n    (n : Nat) (a : HS) :\\n    Submodule.map\\n        (divUniversalHighWindowBaseMultiplierTransition (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j n a)\\n        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j n) ≤\\n      divUniversalHighWindowRelation (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j (n + 1) := by\\n  cases n with\\n  | zero =>\\n      exact map_divUniversalHighWindowBaseMultiplierTransition_relation_zero_le\\n        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j a\\n  | succ n =>\\n      exact map_divUniversalHighWindowBaseMultiplierTransition_relation_succ_le\\n        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n a\\n\\nend HighWindowTransitionRelationZero\\n\\nend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n820:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T03:34:11.225627+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"/-\\nCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\nReleased under Apache 2.0 license as described in the file LICENSE.\\nAuthors: The AlgebraicJacobian Contributors\\n-/\\n\\nimport Mathlib.LinearAlgebra.TensorProduct.Tower\\n\\n/-!\\n# Image transport through a scalar-extension equivalence\\n\\nThis file contains the small linear-algebra bridge used by the high-window\\nfibre model.  An equivalence on the scalar-extended source and target, together\\nwith a commuting square for a map and its base change, transports the image\\nsubmodule.  No geometry, finite-dimensionality, or flatness is involved.\\n-/\\n\\nset_option autoImplicit false\\n\\nuniverse u\\n\\nopen scoped TensorProduct\\n\\nnamespace AlgebraicGeometry\\n\\nsection ImageTransfer\\n\\nvariable {R S : Type u} [CommRing R] [CommRing S] [Algebra R S]\\nvariable {M N : Type u} [AddCommGroup M] [Module R M]\\n  [AddCommGroup N] [Module R N]\\n\\n/-! ## The range of a base-changed map -/\\n\\n/-- Base change commutes with taking the range of a linear map.\\n\\nThe statement is proved here rather than imported from a geometry-specific\\nmodule so that the image-conjugacy theorem below remains inexpensive to use.\\n-/\\ntheorem range_baseChange_linear (f : M →ₗ[R] N) :\\n    LinearMap.range (LinearMap.baseChange S f) =\\n      Submodule.baseChange S (LinearMap.range f) := by\\n  apply le_antisymm\\n  · rw [LinearMap.range_le_iff_comap, eq_top_iff]\\n    rintro z -\\n    induction z with\\n    | zero => simp\\n    | tmul a m =>\\n        rw [Submodule.mem_comap, LinearMap.baseChange_tmul]\\n        exact Submodule.tmul_mem_baseChange_of_mem a\\n          (LinearMap.mem_range_self f m)\\n    | add x y hx hy =>\\n        rw [Submodule.mem_comap, map_add]\\n        exact Submodule.add_mem _ (Submodule.mem_comap.1 hx)\\n          (Submodule.mem_comap.1 hy)\\n  · rw [Submodule.baseChange_eq_span, Submodule.span_le]\\n    rintro _ ⟨y, hy, rfl⟩\\n    obtain ⟨m, rfl⟩ := hy\\n    exact ⟨(1 : S) ⊗ₜ[R] m, by\\n      rw [LinearMap.baseChange_tmul, TensorProduct.mk_apply]⟩\\n\\n/-! ## Transport through a conjugacy square -/\\n\\n/-- The image of `f` after scalar extension, transported through equivalences\\non source and target, is exactly the image of the conjugate map `f'`.\\n\\nThe hypothesis is pointwise so callers can discharge it with the naturality\\nlemma for their chosen fibre equivalences. -/\\ntheorem map_baseChange_range_eq_range_of_conjugate\\n    (f : M →ₗ[R] N)\\n    {M' N' : Type u} [AddCommGroup M'] [Module S M']\\n      [AddCommGroup N'] [Module S N']\\n    (f' : M' →ₗ[S] N')\\n    (eM : (S ⊗[R] M) ≃ₗ[S] M')\\n    (eN : (S ⊗[R] N) ≃ₗ[S] N')\\n    (hconj : ∀ x : S ⊗[R] M,\\n      eN (LinearMap.baseChange S f x) = f' (eM x)) :\\n    Submodule.map eN.toLinearMap\\n        (Submodule.baseChange S (LinearMap.range f)) =\\n      LinearMap.range f' := by\\n  rw [← range_baseChange_linear (S := S) f]\\n  apply le_antisymm\\n  · rintro z ⟨y, hy, rfl⟩\\n    obtain ⟨x, rfl⟩ := hy\\n    change eN (LinearMap.baseChange S f x) ∈ LinearMap.range f'\\n    rw [hconj]\\n    exact LinearMap.mem_range_self f' (eM x)\\n  · rintro z ⟨x, rfl⟩\\n    obtain ⟨y, rfl⟩ := eM.surjective x\\n    refine ⟨LinearMap.baseChange S f y, ?_, hconj y⟩\\n    exact LinearMap.mem_range_self (LinearMap.baseChange S f) y\\n\\nend ImageTransfer\\n\\nend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n822:{\"kind\": \"tool_call\", \"at\": \"2026-07-22T03:34:32.758598+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"command\": \"/bin/bash -lc '$HORIZON_GIT commit -m \\\"DD-R: transport recursive ranges through fibre conjugacy\\\" -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivSchemeHighWindowImageTransfer.lean'\"}, \"usage\": null}\n823:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T03:34:32.758612+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"[main ea15dceb6] DD-R: transport recursive ranges through fibre conjugacy\\n 1 file changed, 94 insertions(+)\\n create mode 100644 MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivSchemeHighWindow