3\\t        (C := C) (pi := pi) hpi g K 1 =\\n   284\\t      msCoherenceUnit C K hpi g := by\\n   285\\t  rw [divUniversalHighWindowClosedCoherenceUnit, msCoherenceUnit]\\n   286\\t  simp only [pow_one, divUniversalHighWindowExponent, one_mul]\\n   287\\t  rw [mul_comm (thetaFieldShiftUnit C K pi (windowM_choice pi hpi g))\\n   288\\t    (thetaFieldShiftUnit C K pi (windowS_choice pi hpi g))]\\n   289\\t\\n   290\\t/-- The divisor of the closed unit is precisely the discrepancy between the\\n   291\\ttransported exponent window and `N+n*S`. -/\\n   292\\ttheorem divOf_divUniversalHighWindowClosedCoherenceUnit (n : Nat) :\\n   293\\t    windowTransportDivisor C K pi exp[n] -\\n   294\\t        (windowN C K hpi g + n • windowS C K hpi g) =\\n   295\\t      Scheme.divOf (relCurve C K ↘ Spec (CommRingCat.of K))\\n   296\\t        (divUniversalHighWindowClosedCoherenceUnit\\n   297\\t          (C := C) (pi := pi) hpi g K n) := by\\n   298\\t  induction n with\\n   299\\t  | zero =>\\n   300\\t      change windowN C K hpi g - (windowN C K hpi g + 0) =\\n   301\\t        Scheme.divOf (relCurve C K ↘ Spec (CommRingCat.of K))\\n   302\\t          (thetaFieldShiftUnit C K pi (windowM_choice pi hpi g) * 1 *\\n   303\\t            (thetaFieldShiftUnit C K pi (windowM_choice pi hpi g))⁻¹)\\n   304\\t      rw [add_zero, mul_one, mul_inv_cancel, Scheme.divOf_one, sub_self]\\n   305\\t  | succ n ih =>\\n\", \"exit_code\": 0}, \"usage\": null}\n879:{\"kind\": \"text\", \"at\": \"2026-07-22T03:51:45.012333+00:00\", \"text\": \"The strict checks are expensive because these declarations carry the entire dependent chart and window tower, but they are progressing without resource exhaustion. The stage-zero proof now avoids the false definitional equality entirely: it transports each basis product through the zero/one window equivalences and proves only the inclusion actually needed by the relation tower.\", \"tool\": \"\", \"data\": {}, \"usage\": null}\n924:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T03:56:35.156269+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"     1\\t/-\\n     2\\tCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\n     3\\tReleased under Apache 2.0 license as described in the file LICENSE.\\n     4\\tAuthors: The AlgebraicJacobian Contributors\\n     5\\t-/\\n     6\\t\\n     7\\timport AlgebraicJacobian.Picard.DivSchemeHighWindowTransitionRelation\\n     8\\t\\n     9\\t/-!\\n    10\\t# Stage-zero compatibility for high-window transitions\\n    11\\t\\n    12\\tThis file supplies the initial step omitted by the recursive successor theorem:\\n    13\\tmultiplication by any base-field section of the multiplier window sends the\\n    14\\ttransported first universal window into the transported universal multiplication\\n    15\\tspan at stage one.\\n    16\\t-/\\n    17\\t\\n    18\\tset_option autoImplicit false\\n    19\\tset_option quotPrecheck false\\n    20\\tset_option backward.isDefEq.respectTransparency false\\n    21\\tset_option maxSynthPendingDepth 8\\n    22\\tset_option maxRecDepth 8000\\n    23\\tset_option linter.unusedSectionVars false\\n    24\\t\\n    25\\tuniverse u\\n    26\\t\\n    27\\topen CategoryTheory Limits TopologicalSpace Opposite\\n    28\\topen scoped TensorProduct\\n    29\\t\\n    30\\tnamespace AlgebraicGeometry\\n    31\\t\\n    32\\topen Scheme Grassmannian\\n    33\\t\\n    34\\tattribute [local instance] Scheme.overModule Scheme.overSectionsAlgebra\\n    35\\t  Scheme.functionFieldOverModule\\n    36\\tattribute [local instance 10000] relCurve.instOver\\n    37\\t\\n    38\\tsection HighWindowTransitionRelationZero\\n    39\\t\\n    40\\tvariable {k : Type u} [Field k] (C : Over (Spec (.of k)))\\n    41\\t  [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\\n    42\\t  [GeometricallyIrreducible C.hom]\\n    43\\tvariable {pi : C.left ⟶ P1 k} [IsFinite pi] [IsDominant pi]\\n    44\\t\\n    45\\tnoncomputable local instance instOverCleftHighWindowTransitionRelationZero :\\n    46\\t    C.left.Over (Spec (.of k)) := ⟨C.hom⟩\\n    47\\t\\n    48\\tvariable [SmoothOfRelativeDimension 1 (C.left ↘ Spec (.of k))] [IsIntegral C.left]\\n    49\\t  [LocallyOfFiniteType (C.left ↘ Spec (.of k))]\\n    50\\t  [QuasiCompact (C.left ↘ Spec (.of k))]\\n    51\\tvariable [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 0)]\\n    52\\t  [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 1)]\\n    53\\tvariable (hpi : pi ≫ P1.structureMap k = C.left ↘ Spec (CommRingCat.of k))\\n    54\\tvariable (g r1 r2 : Nat)\\n    55\\tvariable (b1 : Module.Basis (Fin r1) k\\n    56\\t  ↥(Scheme.divisorSections k (windowM_choice pi hpi g • fiberWeilDivisor pi) ⊤))\\n    57\\tvariable (b2 : Module.Basis (Fin r2) k\\n    58\\t  ↥(Scheme.divisorSections k ((windowS_choice pi hpi g • fiberWeilDivisor pi)\\n    59\\t    + (windowM_choice pi hpi g • fiberWeilDivisor pi)) ⊤))\\n    60\\tvariable (i : (glueData k g r1).J) (j : (glueData k g r2).J)\\n    61\\t\\n    62\\tlocal notation \\\"RZ\\\" => DivCarveChartRing k\\n    63\\t  (windowS_choice pi hpi g • fiberWeilDivisor pi)\\n    64\\t  (windowM_choice pi hpi g • fiberWeilDivisor pi) g r1 r2 b1 b2 i j\\n    65\\tlocal notation \\\"HS\\\" => ↥(Scheme.divisorSections k\\n    66\\t  (windowS_choice pi hpi g • fiberWeilDivisor pi) ⊤)\\n    67\\tlocal notation \\\"HM\\\" => ↥(Scheme.divisorSections k\\n    68\\t  (windowM_choice pi hpi g • fiberWeilDivisor pi) ⊤)\\n    69\\t\\n    70\\tset_option maxHeartbeats 1600000 in\\n    71\\t-- The two seed-window reindexings carry the same product in the function field.\\n    72\\tprivate theorem divUniversalHighWindowShiftMul_zero_comp_zeroEquiv\\n    73\\t    (a : HS) :\\n    74\\t    (divUniversalHighWindowShiftMul (C := C) (pi := pi) hpi g 0 a).comp\\n    75\\t        (divUniversalHighWindowZeroEquiv (C := C) (pi := pi) hpi g).toLinearMap =\\n    76\\t      (divUniversalHighWindowOneEquiv (C := C) (pi := pi) hpi g).toLinearMap.comp\\n    77\\t        (windowShiftMul hpi g a) := by\\n    78\\t  ext x\\n    79\\t  simp only [LinearMap.comp_apply]\\n    80\\t  rw [coe_divUniversalHighWindowShiftMul]\\n    81\\t  change (a : C.left.functionField) * (x : C.left.functionField) =\\n    82\\t    ((windowShiftMul hpi g a x : ↥(Scheme.divisorSections k\\n    83\\t      ((windowM_choice pi hpi g + windowS_choice pi hpi g) •\\n    84\\t        fiberWeilDivisor pi) ⊤)) : C.left.functionField)\\n    85\\t  rw [windowShiftMul, LinearMap.comp_apply, LinearEquiv.coe_coe,\\n    86\\t    LinearEquiv.coe_ofEq_apply, sectionMulBilin_apply_coe]\\n    87\\t\\n    88\\tset_option maxHeartbeats 1600000 in\\n    89\\t-- Base change preserves the seed-window multiplication square.\\n    90\\tprivate theorem divUniversalHighWindowBaseChangeShiftMul_zero_zeroEquiv\\n    91\\t    (a : HS) (x : RZ ⊗[k] HM) :\\n    92\\t    (LinearMap.baseChange RZ\\n    93\\t      (divUniversalHighWindowShiftMul (C := C) (pi := pi) hpi g 0 a))\\n    94\\t        (LinearMap.baseChange RZ\\n    95\\t          (divUniversalHighWindowZeroEquiv (C := C) (pi := pi) hpi g).toLinearMap x) =\\n    96\\t      (LinearMap.baseChange RZ\\n    97\\t        (divUniversalHighWindowOneEquiv (C := C) (pi := pi) hpi g).toLinearMap)\\n    98\\t        (LinearMap.baseChange RZ (windowShiftMul hpi g a) x) := by\\n    99\\t  change\\n   100\\t    ((LinearMap.baseChange RZ\\n   101\\t      (divUniversalHighWindowShiftMul (C := C) (pi := pi) hpi g 0 a)).comp\\n   102\\t        (LinearMap.baseChange RZ\\n   103\\t          (divUniversalHighWindowZeroEquiv (C := C) (pi := pi) hpi g).toLinearMap)) x =\\n   104\\t      ((LinearMap.baseChange RZ\\n   105\\t        (divUniversalHighWindowOneEquiv (C := C) (pi := pi) hpi g).toLinearMap).comp\\n   106\\t          (LinearMap.baseChange RZ (windowShiftMul hpi g a))) x\\n   107\\t  rw [← LinearMap.baseChange_comp, ← LinearMap.baseChange_comp,\\n   108\\t    divUniversalHighWindowShiftMul_zero_comp_zeroEquiv]\\n   109\\t\\n   110\\tset_option maxHeartbeats 1600000 in\\n   111\\t-- A single basis product is one coordinate of the universal multiplication map.\\n   112\\tprivate theorem baseChange_windowShiftMul_finBasis_mem_universalMulSpan\\n   113\\t    (t : Fin (Module.finrank k HS))\\n   114\\t    (x : ↥(divUniversalFstWindow C pi hpi g r1 r2 b1 b2 i j).toSubmodule) :\\n   115\\t    LinearMap.baseChange RZ\\n   116\\t        (windowShiftMul hpi g ((Module.finBasis k HS) t)) x.1 ∈\\n   117\\t      universalMulSpan (hπ := hpi) g r1 r2 b1 b2 i j := by\\n   118\\t  classical\\n   119\\t  refine ⟨Pi.single t x, ?_⟩\\n   120\\t  rw [universalMulMap, LinearMap.sum_apply]\\n   121\\t  simp only [LinearMap.comp_apply, LinearMap.proj_apply]\\n   122\\t  rw [Finset.sum_eq_single t]\\n   123\\t  · rw [Pi.single_eq_same]\\n   124\\t    rfl\\n   125\\t  · intro s _ hst\\n   126\\t    rw [Pi.single_eq_of_ne hst, map_zero]\\n   127\\t    exact (LinearMap.baseChange RZ\\n   128\\t      (windowShiftMul hpi g ((Module.finBasis k HS) s))).map_zero\\n   129\\t  · intro ht\\n   130\\t    exact (ht (Finset.mem_univ t)).elim\\n   131\\t\\n   132\\tset_option maxHeartbeats 1600000 in\\n   133\\t-- The generic stage-zero span is transported from the seed multiplication span.\\n   134\\tprivate theorem divUniversalHighWindowMulSpan_zero_relation_le_one :\\n   135\\t    divUniversalHighWindowMulSpan (C := C) (pi := pi)\\n   136\\t        hpi g r1 r2 b1 b2 i j 0\\n   137\\t        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n   138\\t          hpi g r1 r2 b1 b2 i j 0) ≤\\n   139\\t      divUniversalHighWindowRelation (C := C) (pi := pi)\\n   140\\t        hpi g r1 r2 b1 b2 i j 1 := by\\n   141\\t  classical\\n   142\\t  rw [divUniversalHighWindowRelation_one_transport]\\n   143\\t  rintro _ ⟨v, rfl⟩\\n   144\\t  rw [divUniversalHighWindowMulMap, LinearMap.sum_apply]\\n   145\\t  apply Submodule.sum_mem\\n   146\\t  intro t ht\\n   147\\t  simp only [LinearMap.comp_apply, LinearMap.proj_apply]\\n   148\\t  have hvt := (v t).2\\n   149\\t  rw [divUniversalHighWindowRelation_zero,\\n   150\\t    divUniversalHighWindowStageZero_toSubmodule] at hvt\\n   151\\t  rcases hvt with ⟨x, hx, hxv⟩\\n   152\\t  let x' : ↥(divUniversalFstWindow C pi hpi g r1 r2 b1 b2 i j).toSubmodule :=\\n   153\\t    ⟨x, hx⟩\\n   154\\t  refine ⟨LinearMap.baseChange RZ\\n   155\\t      (windowShiftMul hpi g ((Module.finBasis k HS) t)) x,\\n   156\\t    baseChange_windowShiftMul_finBasis_mem_universalMulSpan\\n   157\\t      (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j t x', ?_⟩\\n   158\\t  rw [← hxv]\\n   159\\t  exact (divUniversalHighWindowBaseChangeShiftMul_zero_zeroEquiv\\n   160\\t    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j\\n   161\\t      ((Module.finBasis k HS) t) x).symm\\n   162\\t\\n   163\\tset_option maxHeartbeats 1600000 in\\n   164\\t-- Unfolding both transported seed stages is definitionally expensive.\\n   165\\t/-- Multiplication by any base-field multiplier preserves the relation tower at\\n   166\\tits initial transition. -/\\n   167\\ttheorem map_divUniversalHighWindowBaseMultiplierTransition_relation_zero_le\\n   168\\t    (a : HS) :\\n   169\\t    Submodule.map\\n   170\\t        (divUniversalHighWindowBaseMultiplierTransition (C := C) (pi := pi)\\n   171\\t          hpi g r1 r2 b1 b2 i j 0 a)\\n   172\\t        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n   173\\t          hpi g r1 r2 b1 b2 i j 0) ≤\\n   174\\t      divUniversalHighWindowRelation (C := C) (pi := pi)\\n   175\\t        hpi g r1 r2 b1 b2 i j 1 :=\\n   176\\t  (map_divUniversalHighWindowBaseMultiplierTransition_le_mulSpan\\n   177\\t    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j 0\\n   178\\t      (divUniversalHighWindowRelation (C := C) (pi := pi)\\n   179\\t        hpi g r1 r2 b1 b2 i j 0) a).trans\\n   180\\t    (divUniversalHighWindowMulSpan_zero_relation_le_one\\n   181\\t      (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j)\\n   182\\t\\n   183\\tset_option maxHeartbeats 1600000 in\\n   184\\t-- The zero branch unfolds the transported seed multiplication span.\\n   185\\t/-- Multiplication by any base-field multiplier preserves the recursive\\n   186\\thigh-window relation tower at every stage. -/\\n   187\\ttheorem map_divUniversalHighWindowBaseMultiplierTransition_relation_le\\n   188\\t    (n : Nat) (a : HS) :\\n   189\\t    Submodule.map\\n   190\\t        (divUniversalHighWindowBaseMultiplierTransition (C := C) (pi := pi)\\n   191\\t          hpi g r1 r2 b1 b2 i j n a)\\n   192\\t        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n   193\\t          hpi g r1 r2 b1 b2 i j n) ≤\\n   194\\t      divUniversalHighWindowRelation (C := C) (pi := pi)\\n   195\\t        hpi g r1 r2 b1 b2 i j (n + 1) := by\\n   196\\t  cases n with\\n   197\\t  | zero =>\\n   198\\t      exact map_divUniversalHighWindowBaseMultiplierTransition_relation_zero_le\\n   199\\t        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j a\\n   200\\t  | succ n =>\\n   201\\t      exact map_divUniversalHighWindowBaseMultiplierTransition_relation_succ_le\\n   202\\t        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n a\\n   203\\t\\n   204\\tend HighWindowTransitionRelationZero\\n   205\\t\\n   206\\tend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n929:{\"kind\": \"text\", \"at\": \"2026-07-22T03:56:40.884463+00:00\", \"text\": \"The stage-zero build has crossed 20 minutes and 26 GB RSS without reaching a heartbeat diagnostic, which indicates elaborator blow-up rather than useful proof search. I’m stopping that run, bisecting the file by declaration, and will replace the offending transported-span proof with a smaller map-level lemma.\", \"tool\": \"\", \"data\": {}, \"usage\": null}\n939:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T04:00:44.712871+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"   230\\t        divUniversalHighWindowThetaSubmodule (C := C) (pi := pi)\\n   231\\t          hpi g r1 r2 b1 b2 i j n x) := by\\n   232\\t  letI := projective_divUniversalHighWindowQuotient\\n   233\\t    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n x\\n   234\\t  exact Module.Projective.of_equiv\\n   235\\t    (divUniversalHighWindowThetaQuotientEquiv (C := C) (pi := pi)\\n   236\\t      hpi g r1 r2 b1 b2 i j n x)\\n   237\\t\\n   238\\tset_option maxHeartbeats 1600000 in\\n   239\\t-- The projective-to-flat transport re-elaborates the dependent theta quotient.\\n   240\\t/-- The relative-theta quotient of a stage is flat. -/\\n   241\\ttheorem flat_divUniversalHighWindowThetaQuotient (n : Nat)\\n   242\\t    (x : DivUniversalHighWindowStage (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n) :\\n   243\\t    Module.Flat RZ\\n   244\\t      (relThetaSections C RZ pi\\n   245\\t          (divUniversalHighWindowExponent (C := C) (pi := pi) hpi g n) ⧸\\n   246\\t        divUniversalHighWindowThetaSubmodule (C := C) (pi := pi)\\n   247\\t          hpi g r1 r2 b1 b2 i j n x) := by\\n   248\\t  letI := projective_divUniversalHighWindowThetaQuotient\\n   249\\t    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n x\\n   250\\t  exact Module.Flat.of_projective\\n   251\\t\\n   252\\t/-! ## The two landed seed stages -/\\n   253\\t\\n   254\\t/-- Reindex the first universal window as high-window stage zero. -/\\n   255\\tnoncomputable def divUniversalHighWindowZeroEquiv :\\n   256\\t    ↥(Scheme.divisorSections k\\n   257\\t        (windowM_choice pi hpi g • fiberWeilDivisor pi) ⊤) ≃ₗ[k]\\n   258\\t      divUniversalHighWindowSections (C := C) (pi := pi) hpi g 0 :=\\n   259\\t  LinearEquiv.ofEq _ _ (congrArg (fun D => Scheme.divisorSections k D ⊤) (by\\n   260\\t    simp [divUniversalHighWindowExponent]))\\n   261\\t\\n   262\\t/-- Reindex the shifted universal window as high-window stage one. -/\\n   263\\tnoncomputable def divUniversalHighWindowOneEquiv :\\n   264\\t    ↥(Scheme.divisorSections k\\n   265\\t        ((windowM_choice pi hpi g + windowS_choice pi hpi g) • fiberWeilDivisor pi) ⊤)\\n   266\\t      ≃ₗ[k] divUniversalHighWindowSections (C := C) (pi := pi) hpi g 1 :=\\n   267\\t  LinearEquiv.ofEq _ _ (congrArg (fun D => Scheme.divisorSections k D ⊤) (by\\n   268\\t    simp [divUniversalHighWindowExponent]))\\n   269\\t\\n   270\\t/-- The universal first carve window, placed at index zero of the high-window tower. -/\\n   271\\tnoncomputable def divUniversalHighWindowStageZero :\\n   272\\t    DivUniversalHighWindowStage (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j 0 :=\\n   273\\t  Grassmannian.congrAmbient\\n   274\\t    (divUniversalHighWindowZeroEquiv (C := C) (pi := pi) hpi g)\\n   275\\t    (divUniversalFstWindow C pi hpi g r1 r2 b1 b2 i j)\\n   276\\t\\n   277\\t/-- The universal second carve window, placed at index one of the high-window tower. -/\\n   278\\tnoncomputable def divUniversalHighWindowStageOne :\\n   279\\t    DivUniversalHighWindowStage (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j 1 :=\\n   280\\t  Grassmannian.congrAmbient\\n   281\\t    (divUniversalHighWindowOneEquiv (C := C) (pi := pi) hpi g)\\n   282\\t    (divUniversalSndWindow C pi hpi g r1 r2 b1 b2 i j)\\n   283\\t\\n   284\\t@[simp]\\n   285\\ttheorem divUniversalHighWindowStageZero_toSubmodule :\\n   286\\t    (divUniversalHighWindowStageZero (C := C) (pi := pi)\\n   287\\t      hpi g r1 r2 b1 b2 i j).toSubmodule =\\n   288\\t      Submodule.map\\n   289\\t        (LinearMap.baseChange RZ\\n   290\\t          (divUniversalHighWindowZeroEquiv (C := C) (pi := pi) hpi g).toLinearMap)\\n   291\\t        (divUniversalFstWindow C pi hpi g r1 r2 b1 b2 i j).toSubmodule :=\\n   292\\t  rfl\\n   293\\t\\n   294\\t@[simp]\\n   295\\ttheorem divUniversalHighWindowStageOne_toSubmodule :\\n   296\\t    (divUniversalHighWindowStageOne (C := C) (pi := pi)\\n   297\\t      hpi g r1 r2 b1 b2 i j).toSubmodule =\\n   298\\t      Submodule.map\\n   299\\t        (LinearMap.baseChange RZ\\n   300\\t          (divUniversalHighWindowOneEquiv (C := C) (pi := pi) hpi g).toLinearMap)\\n   301\\t        (divUniversalSndWindow C pi hpi g r1 r2 b1 b2 i j).toSubmodule :=\\n   302\\t  rfl\\n   303\\t\\n   304\\tend HighWindowStage\\n   305\\t\\n   306\\tend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n943:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T04:00:44.726049+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"     1\\t/-\\n     2\\tCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\n     3\\tReleased under Apache 2.0 license as described in the file LICENSE.\\n     4\\tAuthors: The AlgebraicJacobian Contributors\\n     5\\t-/\\n     6\\t\\n     7\\timport AlgebraicJacobian.Picard.DivSchemeSeedUnivAssemble\\n     8\\timport AlgebraicJacobian.Picard.DivSchemeWindowMulGeneral\\n     9\\t\\n    10\\t/-!\\n    11\\t# Coherence of transported divisor windows at arbitrary exponents\\n    12\\t\\n    13\\tThe field dictionary at exponent `p` differs from the concrete theta reading by\\n    14\\tthe shift unit `u_p = thetaFieldShiftUnit C K pi p`.  Consequently products at\\n    15\\tarbitrary exponents `p` and `q` carry the fixed coherence factor\\n    16\\t\\n    17\\t`u_p * u_q * u_(p+q)^-1`.\\n    18\\t\\n    19\\tThis file generalizes the seed-only `(M,s)` coherence API to all exponents.  It\\n    20\\trecords the divisor of the coherence factor, its action on divisor-section\\n    21\\tspaces, and the corresponding multiplication laws for `thetaFieldRead` and\\n    22\\t`divFamPhi`.\\n    23\\t-/\\n    24\\t\\n    25\\tset_option autoImplicit false\\n    26\\tset_option backward.isDefEq.respectTransparency false\\n    27\\tset_option maxSynthPendingDepth 4\\n    28\\tset_option maxRecDepth 8000\\n    29\\tset_option linter.unusedSectionVars false\\n    30\\t\\n    31\\tuniverse u\\n    32\\t\\n    33\\topen CategoryTheory Limits TopologicalSpace Opposite\\n    34\\topen scoped TensorProduct\\n    35\\t\\n    36\\tnamespace AlgebraicGeometry\\n    37\\t\\n    38\\topen Scheme\\n    39\\t\\n    40\\tattribute [local instance] Scheme.overModule Scheme.overSectionsAlgebra\\n    41\\t  Scheme.functionFieldOverModule\\n    42\\tattribute [local instance 10000] relCurve.instOver\\n    43\\t\\n    44\\tsection Coherence\\n    45\\t\\n    46\\tvariable {k : Type u} [Field k] (C : Over (Spec (.of k)))\\n    47\\tvariable (K : Type u) [Field K] [Algebra k K]\\n    48\\tvariable {pi : C.left ⟶ P1 k} [IsFinite pi]\\n    49\\t\\n    50\\tnoncomputable local instance instOverCleftHighWindowCoherence :\\n    51\\t    C.left.Over (Spec (.of k)) := ⟨C.hom⟩\\n    52\\t\\n    53\\tvariable [SmoothOfRelativeDimension 1 (C.left ↘ Spec (.of k))] [IsIntegral C.left]\\n    54\\t  [LocallyOfFiniteType (C.left ↘ Spec (.of k))]\\n    55\\t  [QuasiCompact (C.left ↘ Spec (.of k))] [IsDominant pi]\\n    56\\tvariable [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 0)]\\n    57\\t  [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 1)]\\n    58\\tvariable [IsIntegral (relCurve C K)]\\n    59\\t  [SmoothOfRelativeDimension 1 (relCurve C K ↘ Spec (CommRingCat.of K))]\\n    60\\t  [QuasiCompact (relCurve C K ↘ Spec (CommRingCat.of K))]\\n    61\\t  [LocallyOfFiniteType (relCurve C K ↘ Spec (CommRingCat.of K))]\\n    62\\t\\n    63\\t/-- Germs commute with restriction maps. -/\\n    64\\tprivate lemma germ_resHom_coherence {X : Scheme.{u}} {W V : X.Opens}\\n    65\\t    (h : W ≤ V) (z : X) (hz : z ∈ W) (t : Γ(X, V)) :\\n    66\\t    (X.presheaf.germ W z hz).hom (X.resHom h t) =\\n    67\\t      (X.presheaf.germ V z (h hz)).hom t :=\\n    68\\t  X.presheaf.germ_res_apply (homOfLE h) z hz t\\n    69\\t\\n    70\\tset_option maxHeartbeats 1600000 in\\n    71\\tset_option synthInstance.maxHeartbeats 600000 in\\n    72\\t/-- The function-field theta reading is multiplicative on an arbitrary pure\\n    73\\tleft tensor and arbitrary scalar-extended right window. -/\\n    74\\ttheorem thetaFieldRead_relThetaWindowEquiv_thetaWindowMul_general\\n    75\\t    (p q : Nat)\\n    76\\t    (hH1p : Subsingleton\\n    77\\t      (relTwistPair C k pi (relThetaCocycle C k pi p)).H1)\\n    78\\t    (hH1q : Subsingleton\\n    79\\t      (relTwistPair C k pi (relThetaCocycle C k pi q)).H1)\\n    80\\t    (hH1pq : Subsingleton\\n    81\\t      (relTwistPair C k pi (relThetaCocycle C k pi (p + q))).H1)\\n    82\\t    (a : ↥(divisorSections k (p • fiberWeilDivisor pi) ⊤))\\n    83\\t    (x : K ⊗[k] ↥(divisorSections k (q • fiberWeilDivisor pi) ⊤)) :\\n    84\\t    thetaFieldRead C K pi (p + q)\\n    85\\t        (relThetaWindowEquiv C K pi (p + q) hH1pq\\n    86\\t          (LinearMap.baseChange K\\n    87\\t            (thetaWindowMul (C := C) (pi := pi) p q a) x)) =\\n    88\\t      thetaFieldRead C K pi p\\n    89\\t          (relThetaWindowEquiv C K pi p hH1p (1 ⊗ₜ a)) *\\n    90\\t        thetaFieldRead C K pi q\\n    91\\t          (relThetaWindowEquiv C K pi q hH1q x) := by\\n    92\\t  by_cases hη : genericPoint (relCurve C K) ∈\\n    93\\t      (relCover C K (fiberTwoCover pi)).V₀\\n    94\\t  · have hcomp := relThetaWindowEquiv_thetaWindowMul_fst\\n    95\\t      C pi K p q a hH1q hH1pq x\\n    96\\t    simp only [thetaWindowMulSectionFst] at hcomp\\n    97\\t    rw [← resHom_relThetaWindowEquiv_one_tmul_fst C pi K p hH1p a] at hcomp\\n    98\\t    have hg := congrArg\\n    99\\t      ((relCurve C K).presheaf.germ\\n   100\\t        ((relCover C K (fiberTwoCover pi)).V₀)\\n   101\\t        (genericPoint (relCurve C K)) hη).hom hcomp\\n   102\\t    rw [map_mul, germ_resHom_coherence (le_inf le_top le_rfl),\\n   103\\t      germ_resHom_coherence (le_inf le_top le_rfl),\\n   104\\t      germ_resHom_coherence (le_inf le_top le_rfl)] at hg\\n   105\\t    rw [thetaFieldRead_eq_germ_fst C K pi _ hη,\\n   106\\t      thetaFieldRead_eq_germ_fst C K pi _ hη,\\n   107\\t      thetaFieldRead_eq_germ_fst C K pi _ hη]\\n   108\\t    exact hg\\n   109\\t  · have hη₁ : genericPoint (relCurve C K) ∈\\n   110\\t        (relCover C K (fiberTwoCover pi)).V₁ :=\\n   111\\t      mem_V₁_of_notMem_V₀ C K pi hη\\n   112\\t    have hcomp := relThetaWindowEquiv_thetaWindowMul_snd\\n   113\\t      C pi K p q a hH1q hH1pq x\\n   114\\t    simp only [thetaWindowMulSectionSnd] at hcomp\\n   115\\t    rw [← resHom_relThetaWindowEquiv_one_tmul_snd C pi K p hH1p a] at hcomp\\n   116\\t    have hg := congrArg\\n   117\\t      ((relCurve C K).presheaf.germ\\n   118\\t        ((relCover C K (fiberTwoCover pi)).V₁)\\n   119\\t        (genericPoint (relCurve C K)) hη₁).hom hcomp\\n   120\\t    rw [map_mul, germ_resHom_coherence (le_inf le_top le_rfl),\\n   121\\t      germ_resHom_coherence (le_inf le_top le_rfl),\\n   122\\t      germ_resHom_coherence (le_inf le_top le_rfl)] at hg\\n   123\\t    rw [thetaFieldRead_eq_germ_snd C K pi _ hη,\\n   124\\t      thetaFieldRead_eq_germ_snd C K pi _ hη,\\n   125\\t      thetaFieldRead_eq_germ_snd C K pi _ hη]\\n   126\\t    exact hg\\n   127\\t\\n   128\\t/-- The coherence unit comparing the product of transported windows at `p`\\n   129\\tand `q` with the transported window at `p + q`. -/\\n   130\\tnoncomputable def windowAddCoherenceUnit (p q : Nat) :\\n   131\\t    (relCurve C K).functionFieldˣ :=\\n   132\\t  thetaFieldShiftUnit C K pi p * thetaFieldShiftUnit C K pi q *\\n   133\\t    (thetaFieldShiftUnit C K pi (p + q))⁻¹\\n   134\\t\\n   135\\t/-- The divisor of the arbitrary-exponent coherence unit is exactly the\\n   136\\tfailure of the chosen transported divisor representatives to be additive. -/\\n   137\\ttheorem divOf_windowAddCoherenceUnit (p q : Nat) :\\n   138\\t    windowTransportDivisor C K pi (p + q) -\\n   139\\t        (windowTransportDivisor C K pi p + windowTransportDivisor C K pi q) =\\n   140\\t      Scheme.divOf (relCurve C K ↘ Spec (CommRingCat.of K))\\n   141\\t        (windowAddCoherenceUnit (pi := pi) C K p q) := by\\n   142\\t  have hinv : Scheme.divOf (relCurve C K ↘ Spec (CommRingCat.of K))\\n   143\\t        (thetaFieldShiftUnit C K pi (p + q))⁻¹ =\\n   144\\t      -Scheme.divOf (relCurve C K ↘ Spec (CommRingCat.of K))\\n   145\\t        (thetaFieldShiftUnit C K pi (p + q)) := by\\n   146\\t    have h0 := Scheme.divOf_mul\\n   147\\t      (relCurve C K ↘ Spec (CommRingCat.of K))\\n   148\\t      (thetaFieldShiftUnit C K pi (p + q))\\n   149\\t      (thetaFieldShiftUnit C K pi (p + q))⁻¹\\n   150\\t    rw [mul_inv_cancel, Scheme.divOf_one] at h0\\n   151\\t    exact (neg_eq_of_add_eq_zero_right h0.symm).symm\\n   152\\t  rw [windowAddCoherenceUnit, Scheme.divOf_mul, Scheme.divOf_mul, hinv,\\n   153\\t    ← divOf_thetaFieldShiftUnit C K pi p,\\n   154\\t    ← divOf_thetaFieldShiftUnit C K pi q,\\n   155\\t    ← divOf_thetaFieldShiftUnit C K pi (p + q),\\n   156\\t    thetaFieldDivisor_add C K pi p q]\\n   157\\t  abel\\n   158\\t\\n   159\\t/-- Multiplication by the coherence unit translates the transported\\n   160\\t`(p + q)` section space to the literal sum of the transported `p` and `q`\\n   161\\tdivisors, compatibly with subtracting an auxiliary divisor. -/\\n   162\\ttheorem map_mulLinear_windowAddCoherenceUnit (p q : Nat)\\n   163\\t    (D : (relCurve C K).CurveDivisor) :\\n   164\\t    Submodule.map\\n   165\\t        (Scheme.mulLinear K\\n   166\\t          ((windowAddCoherenceUnit (pi := pi) C K p q :\\n   167\\t            (relCurve C K).functionFieldˣ) : (relCurve C K).functionField))\\n   168\\t        (Scheme.divisorSections K\\n   169\\t          (windowTransportDivisor C K pi (p + q) - D) ⊤) =\\n   170\\t      Scheme.divisorSections K\\n   171\\t        (windowTransportDivisor C K pi p +\\n   172\\t          windowTransportDivisor C K pi q - D) ⊤ := by\\n   173\\t  rw [map_mulLinear_divisorSections_top K\\n   174\\t    (Units.ne_zero (windowAddCoherenceUnit (pi := pi) C K p q)) _]\\n   175\\t  congr 1\\n   176\\t  rw [show Units.mk0 _\\n   177\\t      (Units.ne_zero (windowAddCoherenceUnit (pi := pi) C K p q)) =\\n   178\\t      windowAddCoherenceUnit (pi := pi) C K p q from Units.ext rfl,\\n   179\\t    ← divOf_windowAddCoherenceUnit (pi := pi) C K p q]\\n   180\\t  abel\\n   181\\t\\n   182\\t/-- Top-window form of `map_mulLinear_windowAddCoherenceUnit`. -/\\n   183\\ttheorem map_mulLinear_windowAddCoherenceUnit_top (p q : Nat) :\\n   184\\t    Submodule.map\\n   185\\t        (Scheme.mulLinear K\\n   186\\t          ((windowAddCoherenceUnit (pi := pi) C K p q :\\n   187\\t            (relCurve C K).functionFieldˣ) : (relCurve C K).functionField))\\n   188\\t        (Scheme.divisorSections K\\n   189\\t          (windowTransportDivisor C K pi (p + q)) ⊤) =\\n   190\\t      Scheme.divisorSections K\\n   191\\t        (windowTransportDivisor C K pi p +\\n   192\\t          windowTransportDivisor C K pi q) ⊤ := by\\n   193\\t  have h := map_mulLinear_windowAddCoherenceUnit (pi := pi) C K p q 0\\n   194\\t  rwa [sub_zero, sub_zero] at h\\n   195\\t\\n   196\\t/-- General `Phi` product law.  A pure `p`-window multiplier times an\\n   197\\tarbitrary scalar-extended `q`-window value is the coherence unit times the\\n   198\\t`(p + q)`-window value of the multiplied tensor. -/\\n   199\\ttheorem divFamPhi_one_tmul_mul_general\\n   200\\t    (p q : Nat)\\n   201\\t    (hH1p : Subsingleton\\n   202\\t      (relTwistPair C k pi (relThetaCocycle C k pi p)).H1)\\n   203\\t    (hH1q : Subsingleton\\n   204\\t      (relTwistPair C k pi (relThetaCocycle C k pi q)).H1)\\n   205\\t    (hH1pq : Subsingleton\\n   206\\t      (relTwistPair C k pi (relThetaCocycle C k pi (p + q))).H1)\\n   207\\t    (a : ↥(divisorSections k (p • fiberWeilDivisor pi) ⊤))\\n   208\\t    (x : K ⊗[k] ↥(divisorSections k (q • fiberWeilDivisor pi) ⊤)) :\\n   209\\t    divFamPhi C K pi p hH1p (1 ⊗ₜ a) * divFamPhi C K pi q hH1q x =\\n   210\\t      ((windowAddCoherenceUnit (pi := pi) C K p q :\\n   211\\t        (relCurve C K).functionFieldˣ) : (relCurve C K).functionField) *\\n   212\\t        divFamPhi C K pi (p + q) hH1pq\\n   213\\t          (LinearMap.baseChange K\\n   214\\t            (thetaWindowMul (C := C) (pi := pi) p q a) x) := by\\n   215\\t  have hphi : ∀ (e : Nat)\\n   216\\t      (hH1 : Subsingleton (relTwistPair C k pi\\n   217\\t        (relThetaCocycle C k pi e)).H1)\\n   218\\t      (y : K ⊗[k] ↥(divisorSections k (e • fiberWeilDivisor pi) ⊤)),\\n   219\\t      divFamPhi C K pi e hH1 y =\\n   220\\t        ((thetaFieldShiftUnit C K pi e :\\n   221\\t          (relCurve C K).functionFieldˣ) : (relCurve C K).functionField) *\\n   222\\t          thetaFieldRead C K pi e\\n   223\\t            (relThetaWindowEquiv C K pi e hH1 y) :=\\n   224\\t    fun _ _ _ => rfl\\n   225\\t  rw [hphi, hphi, hphi,\\n   226\\t    thetaFieldRead_relThetaWindowEquiv_thetaWindowMul_general\\n   227\\t      C K p q hH1p hH1q hH1pq a x,\\n   228\\t    windowAddCoherenceUnit, Units.val_mul, Units.val_mul]\\n   229\\t  rw [Units.val_inv_eq_inv_val]\\n   230\\t  have hne : ((thetaFieldShiftUnit C K pi (p + q) :\\n   231\\t      (relCurve C K).functionFieldˣ) : (relCurve C K).functionField) ≠ 0 :=\\n   232\\t    Units.ne_zero _\\n   233\\t  field_simp\\n   234\\t\\n   235\\tend Coherence\\n   236\\t\\n   237\\tend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n946:{\"kind\": \"text\", \"at\": \"2026-07-22T04:01:37.866146+00:00\", \"text\": \"The bisect confirms the blow-up is already in the seed multiplication square, before any span argument. I’m letting that isolated declaration reach a precise diagnostic while the normalization build runs; once identified, the fix can target the seed reindexing instead of the entire transition file.\", \"tool\": \"\", \"data\": {}, \"usage\": null}\n955:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T04:06:03.280148+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"/-\\nCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\nReleased under Apache 2.0 license as described in the file LICENSE.\\nAuthors: The AlgebraicJacobian Contributors\\n-/\\n\\nimport AlgebraicJacobian.Picard.DivSchemeHighWindowRelations\\nimport AlgebraicJacobian.Picard.SlicingFlatKernel\\n\\n/-!\\n# The relative flatness gate for high-window relations\\n\\nThe recursively generated high-window relation modules are finite, but finiteness and\\nfieldwise persistence do not by themselves make their quotients flat over the possibly\\nnonreduced carve-chart ring.  This file isolates the exact extra input needed by the\\nlanded flattening criterion: a finite syzygy submodule whose image generates the full\\nkernel of the multiplication presentation after tensoring with every residue field.\\n\\nWith that input, the successor quotient is flat; over the Noetherian carve-chart ring it\\nis therefore finite projective.  The first two recursive quotients are already projective\\nand flat, because the carve equations identify them with the two Grassmannian windows.\\n-/\\n\\nset_option autoImplicit false\\nset_option backward.isDefEq.respectTransparency false\\nset_option maxSynthPendingDepth 8\\nset_option maxRecDepth 8000\\nset_option linter.unusedSectionVars false\\n\\nuniverse u\\n\\nopen CategoryTheory TopologicalSpace Opposite\\nopen scoped TensorProduct\\n\\nnamespace AlgebraicGeometry\\n\\nopen Scheme Grassmannian\\n\\nattribute [local instance] Scheme.overModule Scheme.overSectionsAlgebra\\n  Scheme.functionFieldOverModule\\nattribute [local instance 10000] relCurve.instOver\\n\\nsection HighWindowRelationFlat\\n\\nvariable {k : Type u} [Field k] (C : Over (Spec (.of k)))\\n  [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom]\\n  [GeometricallyIrreducible C.hom]\\nvariable {pi : C.left ⟶ P1 k} [IsFinite pi] [IsDominant pi]\\n\\nnoncomputable local instance instOverCleftHighWindowRelationFlat :\\n    C.left.Over (Spec (.of k)) := ⟨C.hom⟩\\n\\nvariable [SmoothOfRelativeDimension 1 (C.left ↘ Spec (.of k))] [IsIntegral C.left]\\n  [LocallyOfFiniteType (C.left ↘ Spec (.of k))]\\n  [QuasiCompact (C.left ↘ Spec (.of k))]\\nvariable [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 0)]\\n  [Module.Finite k (Sheaf.HModule (C.left.moduleKSheaf k) 1)]\\nvariable (hpi : pi ≫ P1.structureMap k = C.left ↘ Spec (CommRingCat.of k))\\nvariable (g r1 r2 : Nat)\\nvariable (b1 : Module.Basis (Fin r1) k\\n  ↥(Scheme.divisorSections k (windowM_choice pi hpi g • fiberWeilDivisor pi) ⊤))\\nvariable (b2 : Module.Basis (Fin r2) k\\n  ↥(Scheme.divisorSections k ((windowS_choice pi hpi g • fiberWeilDivisor pi)\\n    + (windowM_choice pi hpi g • fiberWeilDivisor pi)) ⊤))\\nvariable (i : (glueData k g r1).J) (j : (glueData k g r2).J)\\n\\nlocal notation \\\"RZ\\\" => DivCarveChartRing k\\n  (windowS_choice pi hpi g • fiberWeilDivisor pi)\\n  (windowM_choice pi hpi g • fiberWeilDivisor pi) g r1 r2 b1 b2 i j\\n\\n/-- The quotient by the recursively generated relation module at a high window. -/\\nabbrev divUniversalHighWindowRelationQuotient (n : Nat) : Type u :=\\n  divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n      (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) n ⧸\\n    divUniversalHighWindowRelation (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j n\\n\\nset_option maxHeartbeats 1600000 in\\n-- The fully expanded high-window source and fibre kernel exceed the default elaboration budget.\\n/-- The precise relative persistence condition on a proposed syzygy module for one\\nsuccessor multiplication presentation. -/\\ndef DivUniversalHighWindowSyzygySpans (n : Nat)\\n    (K : Submodule RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n        (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) n))\\n    (L : Submodule RZ\\n      (DivUniversalHighWindowMulSource (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j n K)) : Prop :=\\n  L ≤ LinearMap.ker\\n      (divUniversalHighWindowMulMap (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j n K) ∧\\n    ∀ p : PrimeSpectrum RZ,\\n      LinearMap.ker\\n          ((divUniversalHighWindowMulMap (C := C) (pi := pi)\\n            hpi g r1 r2 b1 b2 i j n K).rTensor p.asIdeal.ResidueField) ≤\\n        LinearMap.range (L.subtype.rTensor p.asIdeal.ResidueField)\\n\\nset_option maxHeartbeats 1600000 in\\n-- The dependent high-window multiplication presentation exceeds the default elaboration budget.\\nset_option synthInstance.maxHeartbeats 400000 in\\n-- Synthesizing finiteness and flatness through the dependent source needs additional search time.\\n/-- A successor high-window quotient is flat once a finite relative syzygy module\\ngenerates the complete kernel on every residue-field fibre. -/\\ntheorem flat_divUniversalHighWindowMulSpanQuotient_of_syzygies (n : Nat)\\n    (K : Submodule RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n        (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) n))\\n    [Module.Finite RZ ↥K]\\n    (L : Submodule RZ\\n      (DivUniversalHighWindowMulSource (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j n K))\\n    (hL : DivUniversalHighWindowSyzygySpans (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j n K L) :\\n    Module.Flat RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n          (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) (n + 1) ⧸\\n        divUniversalHighWindowMulSpan (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j n K) := by\\n  letI := finite_divUniversalHighWindowMulSource\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n K\\n  letI := finite_divUniversalHighWindowAmbient\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j (n + 1)\\n  letI := flat_divUniversalHighWindowAmbient\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j (n + 1)\\n  exact Module.Flat.quotient_range_of_forall_ker_rTensor_residueField_le\\n    (divUniversalHighWindowMulMap (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j n K) L hL.1 hL.2\\n\\nset_option maxHeartbeats 1600000 in\\n-- The dependent high-window quotient type exceeds the default elaboration budget.\\nset_option synthInstance.maxHeartbeats 400000 in\\n-- Projectivity synthesis unfolds the finite-presentation instances for this quotient.\\n/-- Over the Noetherian carve-chart ring, the flat successor quotient supplied by the\\nsyzygy criterion is finite projective. -/\\ntheorem projective_divUniversalHighWindowMulSpanQuotient_of_syzygies (n : Nat)\\n    (K : Submodule RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n        (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) n))\\n    [Module.Finite RZ ↥K]\\n    (L : Submodule RZ\\n      (DivUniversalHighWindowMulSource (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j n K))\\n    (hL : DivUniversalHighWindowSyzygySpans (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j n K L) :\\n    Module.Projective RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n          (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) (n + 1) ⧸\\n        divUniversalHighWindowMulSpan (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j n K) := by\\n  letI := flat_divUniversalHighWindowMulSpanQuotient_of_syzygies\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j n K L hL\\n  letI : Module.Finite RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n          (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) (n + 1) ⧸\\n        divUniversalHighWindowMulSpan (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j n K) := by\\n    infer_instance\\n  letI := Module.finitePresentation_of_finite RZ\\n    (divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n        (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) (n + 1) ⧸\\n      divUniversalHighWindowMulSpan (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j n K)\\n  exact Module.Flat.projective_of_finitePresentation\\n\\nset_option maxHeartbeats 1600000 in\\n-- Rewriting the recursive high-window stage to its multiplication span is elaboration-heavy.\\nset_option synthInstance.maxHeartbeats 400000 in\\n-- The recursive finite-submodule instance requires additional synthesis time.\\n/-- Recursive form of the syzygy criterion: it proves flatness at stage `n + 2`. -/\\ntheorem flat_divUniversalHighWindowRelationQuotient_succ_succ_of_syzygies (n : Nat)\\n    (L : Submodule RZ\\n      (DivUniversalHighWindowMulSource (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j (n + 1)\\n          (divUniversalHighWindowRelation (C := C) (pi := pi)\\n            hpi g r1 r2 b1 b2 i j (n + 1))))\\n    (hL : DivUniversalHighWindowSyzygySpans (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j (n + 1)\\n        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j (n + 1)) L) :\\n    Module.Flat RZ\\n      (divUniversalHighWindowRelationQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j (n + 2)) := by\\n  change Module.Flat RZ\\n    ((divUniversalHighWindowAmbient (C := C) (pi := pi) (hpi := hpi) (g := g)\\n        (r1 := r1) (r2 := r2) (b1 := b1) (b2 := b2) (i := i) (j := j) (n + 2)) ⧸\\n      divUniversalHighWindowMulSpan (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j (n + 1)\\n        (divUniversalHighWindowRelation (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j (n + 1)))\\n  letI := finite_divUniversalHighWindowRelation\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j (n + 1)\\n  exact flat_divUniversalHighWindowMulSpanQuotient_of_syzygies\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j (n + 1)\\n      (divUniversalHighWindowRelation (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j (n + 1)) L hL\\n\\nset_option maxHeartbeats 1600000 in\\n-- Comparing the two expanded stage-zero quotient types exceeds the default budget.\\n/-- Quotient transport from relation stage zero to the first Grassmannian point. -/\\nnoncomputable def divUniversalHighWindowRelationZeroQuotientEquiv :\\n    divUniversalHighWindowRelationQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 0 ≃ₗ[RZ]\\n      divUniversalHighWindowQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 0\\n        (divUniversalHighWindowStageZero (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j) :=\\n  Submodule.Quotient.equiv\\n    (divUniversalHighWindowRelation (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j 0)\\n    (divUniversalHighWindowStageZero (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j).toSubmodule\\n    (LinearEquiv.refl RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi)\\n        (hpi := hpi) (g := g) (r1 := r1) (r2 := r2)\\n        (b1 := b1) (b2 := b2) (i := i) (j := j) 0)) (by\\n      rw [LinearEquiv.refl_toLinearMap, Submodule.map_id]\\n      exact divUniversalHighWindowRelation_zero (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j)\\n\\nset_option maxHeartbeats 1600000 in\\n-- Comparing the two expanded stage-one quotient types exceeds the default budget.\\n/-- Quotient transport from relation stage one to the second Grassmannian point. -/\\nnoncomputable def divUniversalHighWindowRelationOneQuotientEquiv\\n    (hO : Sheaf.h0 (C.left.moduleKSheaf k) = 1)\\n    (hchi : Sheaf.chi (C.left.moduleKSheaf k) = 1 - (g : Int))\\n    (hb : 0 < windowBound pi hpi) :\\n    divUniversalHighWindowRelationQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 1 ≃ₗ[RZ]\\n      divUniversalHighWindowQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 1\\n        (divUniversalHighWindowStageOne (C := C) (pi := pi)\\n          hpi g r1 r2 b1 b2 i j) :=\\n  Submodule.Quotient.equiv\\n    (divUniversalHighWindowRelation (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j 1)\\n    (divUniversalHighWindowStageOne (C := C) (pi := pi)\\n      hpi g r1 r2 b1 b2 i j).toSubmodule\\n    (LinearEquiv.refl RZ\\n      (divUniversalHighWindowAmbient (C := C) (pi := pi)\\n        (hpi := hpi) (g := g) (r1 := r1) (r2 := r2)\\n        (b1 := b1) (b2 := b2) (i := i) (j := j) 1)) (by\\n      rw [LinearEquiv.refl_toLinearMap, Submodule.map_id]\\n      exact divUniversalHighWindowRelation_one_eq_secondWindow\\n        (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j hO hchi hb)\\n\\nset_option maxHeartbeats 1600000 in\\n-- Elaborating the expanded quotient equivalence exceeds the default budget.\\n/-- The relation quotient at stage zero is the first Grassmannian quotient. -/\\ntheorem projective_divUniversalHighWindowRelationQuotient_zero :\\n    Module.Projective RZ\\n      (divUniversalHighWindowRelationQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 0) := by\\n  exact Module.Projective.of_equiv\\n    (divUniversalHighWindowRelationZeroQuotientEquiv\\n      (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j).symm\\n\\nset_option maxHeartbeats 1600000 in\\n-- Synthesizing flatness through the expanded stage-zero quotient exceeds the default budget.\\n/-- The relation quotient at stage zero is flat. -/\\ntheorem flat_divUniversalHighWindowRelationQuotient_zero :\\n    Module.Flat RZ\\n      (divUniversalHighWindowRelationQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 0) := by\\n  letI := projective_divUniversalHighWindowRelationQuotient_zero\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j\\n  exact Module.Flat.of_projective\\n\\nset_option maxHeartbeats 1600000 in\\n-- Elaborating the expanded stage-one quotient equivalence exceeds the default budget.\\n/-- The relation quotient at stage one is the second Grassmannian quotient. -/\\ntheorem projective_divUniversalHighWindowRelationQuotient_one\\n    (hO : Sheaf.h0 (C.left.moduleKSheaf k) = 1)\\n    (hchi : Sheaf.chi (C.left.moduleKSheaf k) = 1 - (g : Int))\\n    (hb : 0 < windowBound pi hpi) :\\n    Module.Projective RZ\\n      (divUniversalHighWindowRelationQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 1) := by\\n  exact Module.Projective.of_equiv\\n    (divUniversalHighWindowRelationOneQuotientEquiv\\n      (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j hO hchi hb).symm\\n\\nset_option maxHeartbeats 1600000 in\\n-- Synthesizing flatness through the expanded stage-one quotient exceeds the default budget.\\n/-- The relation quotient at stage one is flat. -/\\ntheorem flat_divUniversalHighWindowRelationQuotient_one\\n    (hO : Sheaf.h0 (C.left.moduleKSheaf k) = 1)\\n    (hchi : Sheaf.chi (C.left.moduleKSheaf k) = 1 - (g : Int))\\n    (hb : 0 < windowBound pi hpi) :\\n    Module.Flat RZ\\n      (divUniversalHighWindowRelationQuotient (C := C) (pi := pi)\\n        hpi g r1 r2 b1 b2 i j 1) := by\\n  letI := projective_divUniversalHighWindowRelationQuotient_one\\n    (C := C) (pi := pi) hpi g r1 r2 b1 b2 i j hO hchi hb\\n  exact Module.Flat.of_projective\\n\\nend HighWindowRelationFlat\\n\\nend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n957:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T04:06:03.281881+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"/-\\nCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\nReleased under Apache 2.0 license as described in the file LICENSE.\\nAuthors: The AlgebraicJacobian Contributors\\n-/\\n\\nimport Mathlib.LinearAlgebra.TensorProduct.Tower\\n\\n/-!\\n# Image transport through a scalar-extension equivalence\\n\\nThis file contains the small linear-algebra bridge used by the high-window\\nfibre model.  An equivalence on the scalar-extended source and target, together\\nwith a commuting square for a map and its base change, transports the image\\nsubmodule.  No geometry, finite-dimensionality, or flatness is involved.\\n-/\\n\\nset_option autoImplicit false\\n\\nuniverse u\\n\\nopen scoped TensorProduct\\n\\nnamespace AlgebraicGeometry\\n\\nsection ImageTransfer\\n\\nvariable {R S : Type u} [CommRing R] [CommRing S] [Algebra R S]\\nvariable {M N : Type u} [AddCommGroup M] [Module R M]\\n  [AddCommGroup N] [Module R N]\\n\\n/-! ## The range of a base-changed map -/\\n\\n/-- Base change commutes with taking the range of a linear map.\\n\\nThe statement is proved here rather than imported from a geometry-specific\\nmodule so that the image-conjugacy theorem below remains inexpensive to use.\\n-/\\ntheorem range_baseChange_linear (f : M →ₗ[R] N) :\\n    LinearMap.range (LinearMap.baseChange S f) =\\n      Submodule.baseChange S (LinearMap.range f) := by\\n  apply le_antisymm\\n  · rw [LinearMap.range_le_iff_comap, eq_top_iff]\\n    rintro z -\\n    induction z with\\n    | zero => simp\\n    | tmul a m =>\\n        rw [Submodule.mem_comap, LinearMap.baseChange_tmul]\\n        exact Submodule.tmul_mem_baseChange_of_mem a\\n          (LinearMap.mem_range_self f m)\\n    | add x y hx hy =>\\n        rw [Submodule.mem_comap, map_add]\\n        exact Submodule.add_mem _ (Submodule.mem_comap.1 hx)\\n          (Submodule.mem_comap.1 hy)\\n  · rw [Submodule.baseChange_eq_span, Submodule.span_le]\\n    rintro _ ⟨y, hy, rfl⟩\\n    obtain ⟨m, rfl⟩ := hy\\n    exact ⟨(1 : S) ⊗ₜ[R] m, by\\n      rw [LinearMap.baseChange_tmul, TensorProduct.mk_apply]⟩\\n\\n/-! ## Transport through a conjugacy square -/\\n\\n/-- The image of `f` after scalar extension, transported through equivalences\\non source and target, is exactly the image of the conjugate map `f'`.\\n\\nThe hypothesis is pointwise so callers can discharge it with the naturality\\nlemma for their chosen fibre equivalences. -/\\ntheorem map_baseChange_range_eq_range_of_conjugate\\n    (f : M →ₗ[R] N)\\n    {M' N' : Type u} [AddCommGroup M'] [Module S M']\\n      [AddCommGroup N'] [Module S N']\\n    (f' : M' →ₗ[S] N')\\n    (eM : (S ⊗[R] M) ≃ₗ[S] M')\\n    (eN : (S ⊗[R] N) ≃ₗ[S] N')\\n    (hconj : ∀ x : S ⊗[R] M,\\n      eN (LinearMap.baseChange S f x) = f' (eM x)) :\\n    Submodule.map eN.toLinearMap\\n        (Submodule.baseChange S (LinearMap.range f)) =\\n      LinearMap.range f' := by\\n  rw [← range_baseChange_linear (S := S) f]\\n  apply le_antisymm\\n  · rintro z ⟨y, hy, rfl⟩\\n    obtain ⟨x, rfl⟩ := hy\\n    change eN (LinearMap.baseChange S f x) ∈ LinearMap.range f'\\n    rw [hconj]\\n    exact LinearMap.mem_range_self f' (eM x)\\n  · rintro z ⟨x, rfl⟩\\n    obtain ⟨y, rfl⟩ := eM.surjective x\\n    refine ⟨LinearMap.baseChange S f y, ?_, hconj y⟩\\n    exact LinearMap.mem_range_self (LinearMap.baseChange S f) y\\n\\nend ImageTransfer\\n\\nend AlgebraicGeometry\\n\", \"exit_code\": 0}, \"usage\": null}\n964:{\"kind\": \"tool_result\", \"at\": \"2026-07-22T04:07:10.071139+00:00\", \"text\": \"\", \"tool\": \"Bash\", \"data\": {\"content\": \"     1\\t/-\\n     2\\tCopyright (c) 2026 The AlgebraicJacobian authors. All rights reserved.\\n     3\\tReleased under Apache 2.0 license as described in the file LICENSE.\\n     4\\tAuthors: The AlgebraicJacobian Contributors\\n     5\\t-/\\n     6\\t\\n     7\\timport AlgebraicJacobian.Picard.DivSchemeHighWindowH1\\n     8\\timport AlgebraicJacobian.Picard.DivSchemeSeedUniv\\n     9\\timport Mathlib.RingTheory.TensorProduct.Free\\n    10\\t\\n    11\\t/-!\\n    12\\t# Projective stages at every high divisor-scheme window\\n    13\\t\\n    14\\tThe saturation route to flatness uses the windows with exponents `M + n * s`, not\\n    15\\tonly the two carve windows `M` and `M + s`.  This file fixes the types of those stages\\n    16\\tover a carve-chart ring and records the formal algebra which is already available:\\n    17\\t\\n    18\\t* every high-window ambient is finite free, hence projective and flat;\\n    19\\t* `relThetaWindowEquiv` identifies it with the corresponding relative theta sections,\\n    20\\t  using the uniform `H^1` vanishing from `DivSchemeHighWindowH1`;\\n    21\\t* a projective high-window quotient is exactly a Grassmannian point, and its quotient\\n    22\\t  remains finite, projective, and flat after transporting to relative theta sections;\\n    23\\t* the two universal carve windows give the stages at indices zero and one.\\n    24\\t\\n    25\\tConstructing compatible stages at every later index, and identifying their directed\\n    26\\tlimit with the genuine chart-reading quotient, remain the geometric saturation step.\\n    27\\t-/\\n    28\\t\\n    29\\tset_option autoImplicit 